    neighbors = []
    for i in range(1 << n):
        t = bin(i)[2:].zfill(n)
        dist = sum(1 for a, b in zip(s, t) if a != b)
        if dist == k:
            neighbors.append(t)
    return sorted(neighbors)

def check_twin(n, k):
    s1 = '0' * n
    d_s1 = get_neighbors(s1, k)
    for i in range(1, 1 << n):
        s2 = bin(i)[2:].zfill(n)
        d_s2 = get_neighbors(s2, k)
        if d_s1 == d_s2:
            return (s1, s2)
    return None

